            queue_held: false,
            _pending: Task::ready(()),
            feed: None,
            feeding: Arc::default(),
            session: None,
            session_epoch: 0,
            asks: Vec::new(),
            expanded_ask: None,
            steps_shown: HashSet::new(),
            answers: Vec::new(),
            ask_history: HistoryList::answers(),
            _ask_history_load: Task::ready(()),
            ask_session: None,
            ask_session_epoch: 0,
            usage: ProjectUsage::default(),
            output_table: TaskTable::new(),
            output_locked: false,
            header_prompt: HeaderPrompt::default(),
            queue_scroll: ScrollHandle::new(),
            ask_rows: ask_rows(),
            ask_row_ids: RefCell::default(),
            file: None,
            _file_subscriptions: Vec::new(),
            file_split: cx.new(|_| ResizableState::default()),
        }
    }
}

